import * as T from './three.module.js';
import {powerIcon} from './powerups.js';
import {Character} from './character.js';
export class View{
 constructor(canvas){this.scene=new T.Scene();this.scene.background=new T.Color('#66c6eb');this.scene.fog=new T.Fog('#b6e1de',65,205);this.renderer=new T.WebGLRenderer({canvas,antialias:true,powerPreference:'high-performance'});this.mobile=matchMedia('(pointer:coarse)').matches;this.ratio=Math.min(devicePixelRatio,this.mobile?1.35:1.75);this.renderer.setPixelRatio(this.ratio);this.renderer.shadowMap.enabled=!this.mobile;this.renderer.shadowMap.type=T.PCFSoftShadowMap;this.renderer.outputColorSpace=T.SRGBColorSpace;this.renderer.toneMapping=T.ACESFilmicToneMapping;this.renderer.toneMappingExposure=1.15;this.camera=new T.PerspectiveCamera(58,1,.1,400);
 this.scene.add(new T.HemisphereLight('#dff5ff','#b4a267',2));let sun=new T.DirectionalLight('#fff1cf',2.7);sun.position.set(-10,42,-23);sun.target.position.set(0,0,-14);sun.castShadow=true;sun.shadow.mapSize.set(this.mobile?1024:2048,this.mobile?1024:2048);Object.assign(sun.shadow.camera,{left:-23,right:23,top:27,bottom:-27,near:1,far:95});sun.shadow.bias=-.0006;sun.shadow.normalBias=.025;sun.shadow.radius=3;this.scene.add(sun,sun.target);this.sun=sun;
 const sky=new T.Mesh(new T.SphereGeometry(300,16,12),new T.ShaderMaterial({side:T.BackSide,depthWrite:false,vertexShader:'varying vec3 v;void main(){v=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec3 v;void main(){float h=clamp(normalize(v).y*2.,0.,1.);gl_FragColor=vec4(mix(vec3(.71,.89,.94),vec3(.10,.56,.88),h),1.);}'}));this.scene.add(sky);
 this.characters=new Map();this.player=new Character('suri');this.characters.set('suri',this.player);this.scene.add(this.player);this.magnetIcon=powerIcon('magnet');this.magnetIcon.scale.setScalar(.6);this.magnetIcon.visible=false;this.scene.add(this.magnetIcon);
 // Near-overhead sun keeps the cast silhouette close. Contact shadow stays anchored to the board, independent of camera and lane direction.
 let shadowMat=new T.ShaderMaterial({transparent:true,depthWrite:false,uniforms:{opacity:{value:.25}},vertexShader:'varying vec2 v;void main(){v=uv;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}',fragmentShader:'varying vec2 v;uniform float opacity;void main(){float a=pow(max(0.,1.-length((v-.5)*2.)),1.6)*opacity;gl_FragColor=vec4(.14,.12,.08,a);}'});this.contact=new T.Mesh(new T.PlaneGeometry(1.55,2.45),shadowMat);this.contact.rotation.x=-Math.PI/2;this.contact.position.y=.015;this.scene.add(this.contact);
 this.wheelContacts=[];for(let i=0;i<2;i++){const c=new T.Mesh(new T.CircleGeometry(.16,12),new T.MeshBasicMaterial({color:'#493d2c',transparent:true,opacity:.27,depthWrite:false}));c.rotation.x=-Math.PI/2;this.scene.add(c);this.wheelContacts.push(c)}
 this.aura=new T.Mesh(new T.SphereGeometry(1.05,16,10),new T.MeshBasicMaterial({color:'#79e9ff',wireframe:true,transparent:true,opacity:.16}));this.aura.position.y=1;this.aura.visible=false;this.player.add(this.aura);
 const pos=new Float32Array(48*3);for(let i=0;i<48;i++){pos[i*3]=(Math.random()-.5)*15;pos[i*3+1]=Math.random()*3;pos[i*3+2]=-Math.random()*65}let geo=new T.BufferGeometry();geo.setAttribute('position',new T.BufferAttribute(pos,3));this.dust=new T.Points(geo,new T.PointsMaterial({color:'#fff3c3',size:.045,transparent:true,opacity:.5}));this.scene.add(this.dust);this.frames=0;this.elapsed=0;this.low=0;window.addEventListener('resize',()=>this.resize());this.resize()}
 setCharacter(id){
  if(!this.characters.has(id))this.characters.set(id,new Character(id));
  this.scene.remove(this.player);this.player=this.characters.get(id);this.player.visible=true;this.player.death=0;
  this.player.add(this.aura);this.scene.add(this.player);
 }
 resize(){this.renderer.setSize(innerWidth,innerHeight,false);this.camera.aspect=innerWidth/innerHeight;this.camera.updateProjectionMatrix()}
 draw(p,t,mode,speed,dt){let running=mode==='run';this.player.animate(p,t,mode,speed);this.magnetIcon.position.set(p.x,p.y+2.75+Math.sin(t*4)*.06,0);const deck=this.player.board.getWorldPosition(new T.Vector3());const ray=this.sun.position.clone().sub(this.sun.target.position);this.contact.position.set(deck.x-deck.y*ray.x/ray.y,.016,deck.z-deck.y*ray.z/ray.y);this.contact.material.uniforms.opacity.value=.34/(1+p.y*.8);this.contact.scale.set(1+p.y*.20,1+p.y*.17,1);
 this.wheelContacts.forEach((c,i)=>{const wheel=this.player.wheels[i].getWorldPosition(new T.Vector3());c.position.set(wheel.x-wheel.y*ray.x/ray.y,.018,wheel.z-wheel.y*ray.z/ray.y);c.material.opacity=.27*Math.max(0,1-wheel.y*2)});let menu=mode==='menu';const desired=new T.Vector3(menu?6:0,menu?4.8:4.1,menu?9.5:7.8);this.camera.position.lerp(desired,Math.min(1,Math.max(0,dt)*6));this.camera.lookAt(0,menu?1.2:1.1,menu?-8:-19);let fov=(innerWidth<innerHeight?65:58)+(running?Math.max(0,speed-16)*.28:0);this.camera.fov+=(fov-this.camera.fov)*.06;this.camera.updateProjectionMatrix();this.dust.rotation.y=Math.sin(t*.04)*.08;this.renderer.render(this.scene,this.camera);
 // Sustained low FPS lowers render resolution and eliminates expensive shadows.
 if(dt>0&&mode==='run'){this.frames++;this.elapsed+=dt;if(this.elapsed>.8){if(this.frames/this.elapsed<42&&this.low<2){this.low++;this.ratio=Math.max(.75,this.ratio*.75);this.renderer.setPixelRatio(this.ratio);this.renderer.shadowMap.enabled=false;this.dust.visible=false}this.frames=0;this.elapsed=0}}}
}
